<script>
(function(){const btn=document.getElementById('profileMenuBtn'),drop=document.getElementById('profileDropdown');if(btn&&drop)btn.addEventListener('click',e=>{e.stopPropagation();drop.classList.toggle('open')});document.addEventListener('click',e=>{if(drop&&!drop.parentElement.contains(e.target))drop.classList.remove('open')});window.openProfileModal=function(){document.getElementById('profileModalOverlay').classList.add('open')};document.getElementById('profileModalCloseBtn')?.addEventListener('click',()=>document.getElementById('profileModalOverlay').classList.remove('open'));document.getElementById('menuBtn')?.addEventListener('click',()=>document.getElementById('sidebar')?.classList.toggle('open'));document.getElementById('themeToggleBtn')?.addEventListener('click',()=>document.body.classList.toggle('light'));document.querySelectorAll('.side-link[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const id=a.getAttribute('href').slice(1),el=document.getElementById(id);if(!el)return;e.preventDefault();document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));el.classList.add('active');document.querySelectorAll('.side-link').forEach(x=>x.classList.remove('active'));a.classList.add('active');document.getElementById('sidebar')?.classList.remove('open')}));})();
window.openReportDetail=function(button){const modal=document.getElementById('reportDetailModal');document.getElementById('detailPengirim').textContent=button.dataset.pengirim||'-';document.getElementById('detailTujuan').textContent=button.dataset.tujuan||'-';document.getElementById('detailPerihal').textContent=button.dataset.perihal||'-';document.getElementById('detailPrioritas').textContent=button.dataset.prioritas||'-';document.getElementById('detailProyek').textContent=button.dataset.proyek||'-';document.getElementById('detailTanggal').textContent=button.dataset.tanggal||'-';document.getElementById('detailDeskripsi').textContent=button.dataset.deskripsi||'-';const lampiran=button.dataset.lampiran||'';const wrap=document.getElementById('detailLampiranWrap');const link=document.getElementById('detailLampiran');if(lampiran){link.href=lampiran;wrap.style.display='block'}else{wrap.style.display='none'}document.getElementById('detailActions').innerHTML=button.dataset.readonly==='1'?'<span style="font-size:11px;color:var(--text-muted);margin-right:auto">Mode view-only pimpinan — aktivitas satuan tidak dapat diedit dari sini.</span>':'<span style="font-size:11px;color:var(--text-muted);margin-right:auto">Gunakan tombol aksi untuk review laporan yang ditujukan kepada pimpinan.</span>';modal.classList.add('open')};document.getElementById('reportDetailClose')?.addEventListener('click',()=>document.getElementById('reportDetailModal').classList.remove('open'));document.getElementById('reportDetailModal')?.addEventListener('click',e=>{if(e.target.id==='reportDetailModal')e.currentTarget.classList.remove('open')});
</script>
